// Definitive probe: mma.m16n8k16 bf16 fragment layouts via ldmatrix.
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <stdio.h>
#include <stdint.h>

__device__ __forceinline__ void ldmatrix_x4(uint32_t r[4], const void* p) {
    uint32_t a = (uint32_t)__cvta_generic_to_shared(p);
    asm volatile("ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%0,%1,%2,%3}, [%4];\n"
                 : "=r"(r[0]), "=r"(r[1]), "=r"(r[2]), "=r"(r[3]) : "r"(a));
}

// smem: 4 matrices, each 8 rows x 8 bf16, laid out at 128-byte stride, row r of matrix m at offset m*128 + r*16
__global__ void probe(const __nv_bfloat16* gA, float* gD) {
    __shared__ __nv_bfloat16 s[4][8][8];
    int t = threadIdx.x;
    for (int i = t; i < 4*8*8; i += 32) {
        int m = i / 64, rem = i % 64, r = rem / 8, c = rem % 8;
        s[m][r][c] = gA[(m*8 + r)*8 + c];
    }
    __syncthreads();
    int lane = t % 32;
    uint32_t r[4];
    ldmatrix_x4(r, &s[0][lane/8][0]);
    if (t < 32) {
        printf("lane %2d: r0=%08x r1=%08x r2=%08x r3=%08x\n", lane, r[0], r[1], r[2], r[3]);
        gD[lane*4+0] = (float)(r[0] & 0xffff);
        gD[lane*4+1] = (float)(r[0] >> 16);
        gD[lane*4+2] = (float)(r[1] & 0xffff);
        gD[lane*4+3] = (float)(r[1] >> 16);
    }
}

int main() {
    __nv_bfloat16 hA[4*8*8];
    for (int i = 0; i < 4*8*8; i++) hA[i] = __float2bfloat16((float)i);
    __nv_bfloat16 *dA; float *dD;
    cudaMalloc(&dA, 4*8*8*2); cudaMalloc(&dD, 128*4);
    cudaMemcpy(dA, hA, 4*8*8*2, cudaMemcpyHostToDevice);
    probe<<<1, 32>>>(dA, dD);
    cudaDeviceSynchronize();
    // verify: matrix m occupies gA[m*64 + r*8 + c]; lane l: matrix l/8, row l%8
    float hD[128]; cudaMemcpy(hD, dD, 128*4, cudaMemcpyDeviceToHost);
    int errs = 0;
    for (int l = 0; l < 32; l++) {
        int m = l/8, row = l%8;
        float e[4] = {(float)(m*64 + row*8 + 0), (float)(m*64 + row*8 + 1),
                      (float)(m*64 + row*8 + 2), (float)(m*64 + row*8 + 3)};
        for (int i = 0; i < 4; i++)
            if (hD[l*4+i] != e[i]) { errs++; break; }
    }
    printf(errs ? "LDMATRIX PROBE FAILED (%d)\n" : "LDMATRIX PROBE PASSED: r0=row cols0-3, r1=row cols4-7 (matrix l/8, row l%8)\n", errs);
    return errs ? 1 : 0;
}
